class PurchaseOrdersResource:
    def __init__(self, transport: Transport) -> None:
        self._transport = transport

    def approve_purchase_order(self, po_id: str) -> PurchaseOrder:
        """[Buyer] Approve a purchase order - only the current stage's assigned approver may call this"""
        return self._transport.call(
            "pleaxy._generated.api.purchase_orders.approve_purchase_order", po_id=po_id
        )

    def cancel_purchase_order(
        self, po_id: str, *, body: CancelPurchaseOrderInput
    ) -> PurchaseOrder:
        """[Buyer] Cancel a purchase order"""
        return self._transport.call(
            "pleaxy._generated.api.purchase_orders.cancel_purchase_order",
            po_id=po_id,
            body=body,
        )

    def close_purchase_order(self, po_id: str) -> PurchaseOrder:
        """[Buyer] Manually close out a purchase order"""
        return self._transport.call(
            "pleaxy._generated.api.purchase_orders.close_purchase_order", po_id=po_id
        )

    def create_purchase_order(self, *, body: CreatePurchaseOrderInput) -> PurchaseOrder:
        """[Buyer] Create a purchase order"""
        return self._transport.call(
            "pleaxy._generated.api.purchase_orders.create_purchase_order", body=body
        )

    def flip_purchase_order_to_invoice(
        self, po_id: str, *, buyer: Union[Unset, str] = UNSET
    ) -> PurchaseOrderSupplierView:
        """[Supplier] Convert an approved purchase order into an invoice. When two buyers issued the same PO id, add ?buyer=<buyer Workspace ID> (409 PO_ID_AMBIGUOUS otherwise)."""
        return self._transport.call(
            "pleaxy._generated.api.purchase_orders.flip_purchase_order_to_invoice",
            po_id=po_id,
            buyer=buyer,
        )

    def get_purchase_order(
        self, po_id: str, *, buyer: Union[Unset, str] = UNSET
    ) -> Union["PurchaseOrder", "PurchaseOrderSupplierView"]:
        """[Both] Get a single purchase order. A Supplier caller gets a reduced view - no costCenter/budgetOwner/buyerName/notes, no AWS sync state, and approval collapsed to a bare status. A Supplier whose id two buyers both issued gets 409 PO_ID_AMBIGUOUS and picks one with ?buyer=<buyer Workspace ID>."""
        return self._transport.call(
            "pleaxy._generated.api.purchase_orders.get_purchase_order",
            po_id=po_id,
            buyer=buyer,
        )

    def list_purchase_orders(
        self, *, from_: Union[Unset, str] = UNSET, to: Union[Unset, str] = UNSET
    ) -> List[Union["PurchaseOrder", "PurchaseOrderSupplierView"]]:
        """[Both] List purchase orders - optionally scoped to a createdAt range via ?from=&to=. A Supplier caller gets a reduced view (see GetPurchaseOrder)."""
        return self._transport.call(
            "pleaxy._generated.api.purchase_orders.list_purchase_orders",
            from_=from_,
            to=to,
        )

    def reassign_purchase_order_approval_stage(
        self, po_id: str, *, body: ReassignApprovalStageInput
    ) -> PurchaseOrder:
        """[Buyer, administrator] Reassign one pending approval step of this order to a different named employee. An approval step is actionable only by the employee it names, so this is the only way to move a step whose approver is gone or unassigned."""
        return self._transport.call(
            "pleaxy._generated.api.purchase_orders.reassign_purchase_order_approval_stage",
            po_id=po_id,
            body=body,
        )

    def reject_purchase_order(self, po_id: str) -> PurchaseOrder:
        """[Buyer] Reject a purchase order - only the current stage's assigned approver may call this"""
        return self._transport.call(
            "pleaxy._generated.api.purchase_orders.reject_purchase_order", po_id=po_id
        )

    def submit_purchase_order_draft(self, po_id: str) -> PurchaseOrder:
        """[Buyer] Submit a draft purchase order for approval"""
        return self._transport.call(
            "pleaxy._generated.api.purchase_orders.submit_purchase_order_draft",
            po_id=po_id,
        )

    def update_purchase_order(
        self, po_id: str, *, body: UpdatePurchaseOrderInput
    ) -> PurchaseOrder:
        """[Buyer] Update a purchase order's bookkeeping metadata - not available once it's closed/canceled/paid"""
        return self._transport.call(
            "pleaxy._generated.api.purchase_orders.update_purchase_order",
            po_id=po_id,
            body=body,
        )


